const CAPITAL_COLORS = {Citadelle:'#d7c177',Sylve:'#77b96b',Forteresse:'#a59a8f',Hameau:'#d8a85c',Nécropole:'#9c7ad6',Abîme:'#ba5f8b',Volcan:'#d35f45',Lagune:'#48a3bf',Désert:'#d7aa4d',Tour:'#6da7d9',Cénote:'#4cc3ca',Bastion:'#c27648',Tertre:'#9b8055',Empyrée:'#8fc7ff',Bosquet:'#73b96f'};
const state = { search: '', activeCapital: 'Toutes', artIndex: {} };
const byId = id => document.getElementById(id);
function displayHp(c){ return c.health; }
function quoteFor(c){ return c.quote || ''; }
function sizeLabel(c){ return c.size ? `${c.size} m` : ''; }
function parseCreatureImage(image=''){
  const m=String(image).match(/^img\/(.+) (\d+)\.png$/);
  return m ? {base:m[1], num:+m[2]} : null;
}
function imageVariantsFor(c){
  const parsed=parseCreatureImage(c.image);
  if(!parsed) return c.image ? [c.image] : [];
  const nums=(typeof IMG_VARIANTS!=='undefined' && IMG_VARIANTS[parsed.base]) || null;
  if(nums && nums.length) return nums.map(n=>`img/${parsed.base} ${n}.png`);
  return [c.image];
}
function currentArtIndex(c){
  const variants=imageVariantsFor(c);
  if(!variants.length) return 0;
  return ((state.artIndex[c.id]||0) % variants.length + variants.length) % variants.length;
}
function currentImageFor(c){
  const variants=imageVariantsFor(c);
  return variants[currentArtIndex(c)] || c.image || '';
}
function cycleCardArt(id, ev){
  if(ev){ ev.preventDefault(); ev.stopPropagation(); }
  const c=CREATURES.find(x=>x.id===Number(id));
  if(!c) return;
  const variants=imageVariantsFor(c);
  if(variants.length<2) return;
  state.artIndex[c.id]=(currentArtIndex(c)+1)%variants.length;
  render();
}
function cardView(c){
  const color=CAPITAL_COLORS[c.capital]||'#c9aa69';
  const variants=imageVariantsFor(c);
  const artSrc=currentImageFor(c);
  const artIdx=currentArtIndex(c);
  const img=artSrc?`<img src="${encodeURI(artSrc)}" alt="${c.name}" decoding="async">`:'';
  const cycleBtn=variants.length>1?`<button type="button" class="art-cycle" onclick="cycleCardArt(${c.id}, event)" title="Image suivante (${artIdx+1}/${variants.length})" aria-label="Image suivante de ${c.name}">↻ <small>${artIdx+1}/${variants.length}</small></button>`:'';
  const size=sizeLabel(c);
  return `<article class="ff-card ${c.rarity}" style="--faction:${color}">
    <header class="card-title"><span>${c.name}</span><b>${c.cost}</b></header>
    <div class="card-art">${img}<i>${c.capital}</i>${size?`<em class="card-size">${size}</em>`:''}${cycleBtn}</div>
    <div class="type-line">Créature · ${c.origin} · ${c.natures.join(' / ')}</div>
    <blockquote>${quoteFor(c)}</blockquote>
    <footer class="card-stats"><span><small>ATQ</small>${c.attack}</span><span><small>HP</small>${displayHp(c)}</span></footer>
  </article>`;
}
function filteredCreatures(){
  const q=state.search.trim().toLowerCase();
  return CREATURES.filter(c=>(state.activeCapital==='Toutes'||c.capital===state.activeCapital)&&(!q||[c.name,c.capital,c.origin,c.rarity,...c.roles,...c.natures].join(' ').toLowerCase().includes(q)))
    .sort((a,b)=>b.power-a.power || b.popularity-a.popularity || a.name.localeCompare(b.name,'fr'));
}
function setFilter(cap){ state.activeCapital=cap; render(); }
function setSearch(v){ state.search=v; render(); }
function renderList(){
  const caps=['Toutes',...Array.from(new Set(CREATURES.map(c=>c.capital))).sort((a,b)=>a.localeCompare(b,'fr'))];
  const picks=filteredCreatures();
  return `<section class="showcase panel">
    <div class="section-head">
      <div>
        <p class="eyebrow">Bestiaire</p>
        <h2>Liste des Cartes</h2>
        <p>${picks.length} carte${picks.length>1?'s':''} affichée${picks.length>1?'s':''} — filtre par faction ou cherche un nom, un rôle, une origine.</p>
      </div>
      <div class="searchbox">
        <input value="${state.search.replaceAll('"','&quot;')}" oninput="setSearch(this.value)" placeholder="Chercher dragon, caster, Nécropole…">
      </div>
    </div>
    <div class="filters">${caps.map(c=>`<button class="${state.activeCapital===c?'active':''}" onclick="setFilter('${c.replaceAll("'","\\'")}')">${c}</button>`).join('')}</div>
    <div class="card-gallery">${picks.map(c=>cardView(c)).join('')||'<em>Aucune carte ne correspond à ce filtre.</em>'}</div>
  </section>`;
}
function render(){
  byId('app').innerHTML=`<header class="topbar">
    <div>
      <p class="eyebrow">Fantasia Fauna</p>
      <h1>Liste des Cartes</h1>
      <p class="subtitle">Consulte le bestiaire : factions, capacités, stats et illustrations.</p>
    </div>
    <div class="stats"><span>${CREATURES.length} créatures</span><span>${filteredCreatures().length} affichées</span></div>
  </header>
  <main>${renderList()}</main>`;
}
